You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

\paragraph{Problem Setup and Notation.}
Throughout most of the paper, we will focus on a linear system $\A\x = \b$ where $\A \in \R^{m \times n}$ and $\b \in \R^m$. Let $\rank(\A) = r$ and $\{\sigma_i\}_{i=1}^r$ be the decreasing singular values of $\A$.  There are two cases we consider. In the first case where $\b \in \range(\A)$, the linear system is consistent and has one unique min-length solution $\x^* = \A^\dagger \b$. In the second case where $\b \notin \range(\A)$, the linear system is inconsistent and there is no exact solution, and we denote $\x^* = \A^\dagger \b$ as the solution of the least squares problem $\min_{\x} \|\A\x - \b\|$.
As a special case, we also consider solving a symmetric positive semidefinite definite (psd) linear system $\A\x = \b$ where $\A\in\mathcal S_n$, $\b\in\R^n$, and we use $\mathcal S_n$ to denote the psd cone.

For vector $\v$, we use $\|\v\|$ to denote its Euclidean norm, and for a psd matrix $\M$, we denote $\|\v\|_\M := \sqrt{\v^\top\M\v}$. For matrix $\A$, we denote $\|\A\|_2$ and $\|\A\|_F$ as its operator norm and Frobenius norm respectively, and denote $\kappa(\A)$ as its condition number. We also define the averaged condition number of $\A$ as $\bar{\kappa}(\A) := \frac{\|\A\|_F \|\A^\dagger\|_2}{\sqrt{\rank(\A)}}\leq \kappa(\A)$, which arises in the analysis of our algorithms. For $1\leq k\leq \rank(\A)$, we denote the best rank-$k$ approximation of $\A$ as $\A_k := \argmin_{\rank(\hat{\A}) = k} \|\A-\hat{\A}\|_2$, and denote $\bar{\kappa}_k := \bar{\kappa}(\A-\A_k)$ (i.e., the averaged condition number of the tail of the spectrum). Let $\{\sigma_i\}_{i=1}^r$ be the singular values of $\A$ in decreasing order, if we assume that there exists $k$ such that $\sigma_i/\sigma_r = O(1)$ holds for all $i\geq k$, then we have $\bar{\kappa}_k = (\frac{1}{r-k}\sum_{j>k}^r \sigma_j^2 / \sigma_r^2)^{1/2} = O(1)$. For simplicity of presentation, throughout the paper we assume that $\bar{\kappa}_k< m^4$, which is a rather loose condition. For two $n \times n$ psd matrices $\A$ and $\B$, we say $\A \approx_{1+\epsilon} \B$ when $\frac{1}{1+\epsilon} \A \preceq \B \preceq (1+\epsilon)\A$ where $\preceq$ denotes the matrix ordering.

For $1 \leq \tau \leq m$, we use $\tbinom{[m]}{\tau}$ to denote the set of all the $\tau$-element subsets of $[m] = \{1, 2, \ldots, m\}$. For each $S\in\tbinom{[m]}{\tau}$, we use $\I_S\in\R^{\tau \times m}$ to denote the matrix obtained from $m\times m$ identity matrix $\I$ by only retaining the rows whose indices are in $S$. For matrix $\L \in \R^{m \times m}$ and subset $S\in\tbinom{[m]}{\tau}$, we use $\L_{S, S} = \I_S\L\I_S^\top  \in \R^{\tau \times \tau}$ to denote the principal submatrix located at the intersection of the rows and columns with indices from $S$, we also denote $\L_{:,S} = \L\I_S^\top$ and $\L_{S,:} = \I_S \L$ respectively. For a square $n\times n$ matrix $\L$, we use $\adj(\L)$ to denote its adjugate matrix, which is an $n\times n$ matrix such that $\adj(\L)_{ij} = (-1)^{i+j}\det(\L_{[n]\backslash j,[n]\backslash i})$.

\begin{definition}[$k$-DPP]
Given a PSD matrix $\L\in\R^{m \times m}$, a $k$-$\dpp$ is a distribution on $\tbinom{[m]}{k}$ such that $\Pr\{S\} \propto \det(\L_{S,S})$ where $S$ satisfies $|S| = k$. We denote it as $k$-$\dpp(\L)$.
\end{definition}

\begin{algorithm}[!ht]
\caption{Down-up walk on the complement distribution for a discrete measure $\mu$.}
\label{alg:dpp_sample}
\begin{algorithmic}[1]
\For{$i = 0, 1, 2, \ldots$}
\State From all $t$-sized supersets of $S_i$, select one uniformly at random and name it $T_i$;
\State Select among $k$-sized subsets of $T_i$ a random set $S_{i+1}$ with $\Pr\{S_{i+1}\}\propto \mu(S_i)$.
\EndFor
\end{algorithmic}
\end{algorithm}

\begin{definition} \label{hada} The Hadamard matrix $\H_{2^k}$ of dimension $2^k \times 2^k$ is obtained using the following recurrence relation
\begin{align*}
    \H_0 &= [1],\qquad
    \H_{2n} = \begin{bmatrix}
        \H_n & \H_n \\
        \H_n & -\H_n
    \end{bmatrix}.
\end{align*}
\end{definition}

\begin{definition} \label{def:RHT}
The randomized Hadamard transform (RHT) of an $m \times n$ matrix $\A$ is the product $\frac{1}{\sqrt{m}}\H\D\A$, where $\D$ is a random $m \times m$ diagonal matrix whose entries are independent random $\pm1$ signs. By padding $\A$ with zero rows if necessary, we may assume that $n$ is a power of~2. 
\end{definition}

\begin{lemma}[Convergence of CG, \cite{h18}]
\label{lem:cg}
Consider solving positive semidefinite linear system $\A\A^\top \u = \b$ where $\A\in\R^{\tau \times n}, \b \in\R^{\tau}$ are given. Let $\kappa := \kappa(\A)$ be the condition number and $\u^* = (\A\A^\top)^{\dagger}\b$ be the min-length solution. Then, running conjugate gradient by starting from $\u_0 = \mathbf{0}$ will yield the following convergence result:
\begin{align*}
\|\u_s - \u^*\|_{\A\A^\top} \leq 2 \left(\frac{\kappa - 1}{\kappa+1} \right)^s \|\u^*\|_{\A\A^\top}.
\end{align*}
We denote the output of conjugate gradient as $\u_s = \mathrm{CG}(\A,\b,s)$.
\end{lemma}

\begin{lemma}[Adapted from Theorem 1.4 in \cite{chenakkod2023optimal}]\label{lem:precondition_sparse}
Given $\A\in\R^{n \times d}, \epsilon < 1/2$, $\delta < 1/2$, in time $O(\nnz(\A)\log(d / \delta) / \epsilon + d^2\log^4(d/\delta)/\epsilon^6)$ we can compute $\mathbf{\Phi}\A$ where $\mathbf{\Phi}\in\R^{\phi \times n}$ is an embedding matrix with $\phi = O((d+\log(1/\delta)) / \epsilon^2)$, such that with probability $1-\delta$ we have
\begin{align*}
\forall \x\in\R^d, ~~\frac{1}{1+\epsilon} \|\A\x\| \leq \|\mathbf{\Phi}\A\x\| \leq (1+\epsilon) \|\A\x\|.
\end{align*}
\end{lemma}

\begin{algorithm}[!ht]
\caption{Fast Kaczmarz-type solver for consistent linear systems.}
\label{alg:main}
\begin{algorithmic}[1]
\State \textbf{Input: }matrix $\A\in\R^{m\times n}$, vector $\b \in \R^m$, sample size $\tau$, iterate $\x_0$, inner iteration $s_{\max}$, outer iteration $t_{\max}$;
\State Compute $\A \leftarrow \frac{1}{\sqrt{m}}\H\D\A$ and $\b \leftarrow \frac{1}{\sqrt{m}}\H\D\b$; \Comment{Takes $O(mn \log m)$ time.}
\For{$t = 0, 1, \ldots, t_{\max}-1$}
\State Generate $\tilde{S}$ by calling Algorithm~\ref{alg:dpp_sample_real}; \Comment{Takes $O(\tau)$ time.}
\State Compute $\tilde{\A} \leftarrow \I_{\tilde{S}}\A$; \Comment{Subsampling: takes $O(n\tau)$ time.}
\State Compute $\tilde{\b} \leftarrow \I_{\tilde{S}}\A\x_t - \I_{\tilde{S}}\b$; \Comment{Takes $O(n\tau)$ time.}
\State Generate preconditioner $\M$ by calling Algorithm~\ref{alg:preconditioner} with $\tilde{\A}$; \Comment{Takes $\tilde{O}(n\tau + \tau^\omega)$ time.}
\State Compute $\u_{s_{\max}}\leftarrow\mathrm{CG}(\M^\top\tilde{\A}, \M^\top \tilde{\b}, s_{\max})$ with Lemma~\ref{lem:cg}; \Comment{Takes $O(n\tau s_{\max})$ time.}
\State Compute $\w_t \leftarrow \tilde{\A}^\top \M \u_{s_{\max}}$; \Comment{Takes $O(n\tau)$ time.}
\State Update $\x_{t+1} \leftarrow \x_t - \w_t$; \Comment{Takes $O(n)$ time.}
\EndFor \\
\Return $\tilde{\x} = \x_{t_{\max}}$; \Comment{Solves $\A\x=\b$.}
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!ht]
\caption{Fast coordinate descent-type solver for linear systems.}
\label{alg:main_2}
\begin{algorithmic}[1]
\State \textbf{Input: }matrix $\A\in\R^{m\times n}$, vector $\c \in \R^n$, uniform sample size $\tau$, iterate $\x_0$, inner iteration $s_{\max}$, outer iteration $t_{\max}$;
\State Compute $\A \leftarrow \frac{1}{\sqrt{n}}\A\D\H$ and $\c \leftarrow \frac{1}{\sqrt{n}}\H\D\c$; \Comment{Takes $O(mn \log n)$ time.}
\State Compute $\y_0 \leftarrow \A\x_0$; \Comment{Invariant: $\y_t = \A\x_t$.}
\For{$t = 0, 1, \ldots, t_{\max}-1$}
\State Generate $\tilde{S}$ by calling Algorithm~\ref{alg:dpp_sample_real}; \Comment{Takes $O(\tau)$ time.}
\State Compute $\tilde{\A} \leftarrow \A\I_{\tilde{S}}^\top$; \Comment{Subsampling: takes $O(m\tau)$ time.}
\State Compute $\tilde{\c} \leftarrow \tilde{\A}^\top\y_t - \I_{\tilde{S}}\c$; \Comment{Takes $O(m\tau)$ time.}
\State Generate preconditioner $\M$ by calling Algorithm~\ref{alg:preconditioner} with $\tilde{\A}^\top$; \Comment{Takes $\tilde{O}(m\tau + \tau^\omega)$ time.}
\State Compute $\w_{s_{\max}}\leftarrow\mathrm{CG}(\M^\top\tilde{\A}^\top, \M^\top \tilde{\c}, s_{\max})$ with Lemma~\ref{lem:cg}; \Comment{Takes $O(m\tau s_{\max})$ time.}
\State Compute $\x_{t+1} \leftarrow \x_t - \I_{\tilde{S}}^\top \w_{s_{\max}}$; \Comment{Takes $O(\tau)$ time.}
\State Compute $\y_{t+1} \leftarrow \y_t - \tilde{\A} \w_{s_{\max}}$; \Comment{Takes $O(m\tau)$ time.}
\EndFor \\
\Return $\tilde{\x} = \frac{1}{\sqrt{n}}\D\H \x_{t_{\max}}$; \Comment{Solves $\A^\top\A\x=\c$.}

\end{algorithmic}
\end{algorithm}

\begin{lemma}[Improved bound]\label{lem:improve_bound}
Given matrix $\A\in\R^{m\times n}$ with rank $r$.
Let $S_{\dpp}\sim k'$-$\dpp(\A\A^\top)$ where $k'<r$, let $\I_S = \I_{S_{\dpp}} \in \R^{k' \times m}$ be the corresponding sampling matrix and define the projection matrix $\P_{S_{\dpp}} := \A^\top\I_S^\top (\I_S\A\A^\top\I_S^\top)^\dagger\I_S \A$. For any $k < k'$ we have
\begin{align}\label{eq:proj_lower_bound}
\lambda_{\min}^+(\E[\P_{S_{\dpp}}]) \geq \frac{k'-k}{k'-k-1 + (r-k)\bar{\kappa}_{k}^2}.
\end{align}
\end{lemma}

\begin{lemma}[Theorem 3 in \cite{alv22}]
\label{lem:anari_main_2}
Given a strongly Rayleigh distribution $\mu \in \R^{\tbinom{[m]}{k}}$ and marginal overestimates $q_i \geq \Pr_{T\sim\mu}\{i\in T\}$ for $i\in[m]$. Let $K := \sum_{i\in [m]} q_i$, there is an algorithm that outputs a sample from a distribution with total variation distance $m^{-O(1)}$ from $\mu$ in time bounded by $O(\log^3 m)$ calls to $\mathcal{T}_\mu(O(K), k)$, where $\mathcal{T}_\mu(t, k)$ is the time it takes to produce a sample from $\mu$ conditioned on all elements of the sample being a subset of a fixed set $T$ of size $|T| = t$. 
\end{lemma}

\begin{remark}\label{rem:anari_constant}
In Algorithm~\ref{alg:dpp_sample}, we give the sampling procedure claimed by Lemma~\ref{lem:anari_main_2} under the additional ``isotropic'' assumption, i.e., that the marginal overestimates are all uniform. Moreover, the $m^{-O(1)}$ term in Lemma~\ref{lem:anari_main_2} is specified as $m^{-9}$ in the proof of \cite{alv22}.
\end{remark}

\begin{algorithm}[!ht]
\caption{$k$-DPP sampling algorithm based on \cite{alv22} (Ghost Algorithm).}
\label{alg:dpp_sample_ghost}
\begin{algorithmic}[1]
\State \textbf{Input: }$m, k, t, \mathrm{iter}, \mathrm{call}, \mathcal{O}$;
\State \textbf{Initialize }$S_0 \in  \tbinom{[m]}{k}, T_0 \gets \varnothing$; \Comment{By calling $\tilde{O}(k)$ times the oracle.}
\For{$i = 0, 1, 2, \ldots, \mathrm{iter}-1$} \Comment{$\mathrm{iter} = O(\log^3 m)$.}
\State \textbf{Initialize }$T_{i, 0} \gets T_i$;
\For{$j = 0, 1, 2, \ldots, \mathrm{call}-1$} \Comment{$\mathrm{call} \geq Ck$ for some $C=O(1)$.}
\State Sample $i_j$ by calling $ \mathcal{O}$;
\If{$i_j \in S_i \cup T_{i,j}$}:
\State $T_{i, j+1} = T_{i, j}$;
\Else: 
\State $T_{i, j+1} = T_{i,j} \cup \{i_j\}$;
\EndIf
\EndFor
\State \textbf{Update }$T_{i+1} \gets T_{i, \mathrm{call}}$; \Comment{Up-walk step by calling $ \tilde{O}(t-k)$ times the oracle.}
\State \textbf{Update }$S_{i+1} \subseteq S_i \cup T_{i+1}$; \Comment{Down-walk sampling from a $k$-DPP restricted to $S_i \cup T_{i+1}$.}
\EndFor \\
\Return $S_{\mathrm{iter}}$.
\end{algorithmic}
\end{algorithm}

\begin{lemma}[Coupling]\label{lem:main_coupling}
Given matrix $\A\in\R^{m\times n}$, denote $\mathbf{Q} = \frac{1}{\sqrt{m}}\H \mathbf{D}$ as the RHT matrix and $\bar{\A} = \Q\A$ as the preprocessed matrix. Suppose we have an oracle $\mathcal{O}$ that can uniformly sample one element from $[m]$. Conditioned on an event that holds with probability $0.99$ (and only depends on RHT), for $k \geq \log m$ and $\delta = m^{-O(1)}$, there is a coupling $(\tilde{S}, S_{\dpp})$ where $\tilde{S}$ is sampled according to Algorithm~\ref{alg:dpp_sample_real} with choice $\tau \geq Ck\log^3 m$ for some constant $C=O(1)$, and $S_{\dpp}\sim k$-$\dpp(\bar{\A}\bar{\A}^\top)$, such that with probability $1 - \delta$, we have $S_{\dpp} \subseteq \tilde{S}$.
\end{lemma}

\begin{algorithm}[!ht]
\caption{Sample by using uniform sampling oracle $\mathcal{O}$.}
\label{alg:dpp_sample_real}
\begin{algorithmic}[1]
\State \textbf{Input: }$m, \tau, \mathcal{O}$;
\State \textbf{Initialize }$\tilde{S}_0 \gets \varnothing$;
\For{$\ell = 0, 1, 2, \ldots, \tau-1$}
\State Sample $i_\ell$ by calling $\mathcal{O}$;
\If{$i_\ell \in \tilde{S}_\ell$}:
\State $\tilde{S}_{\ell+1} = \tilde{S}_\ell$;
\Else: 
\State $\tilde{S}_{\ell+1} = \tilde{S}_\ell \cup \{i_\ell\}$;
\EndIf
\EndFor \\
\Return $\tilde{S} = \tilde{S}_N$.
\end{algorithmic}
\end{algorithm}

\begin{lemma}
\label{lem:project_order}
Given matrix $\A\in\R^{m \times n}$, for any subsets $S_1 \subseteq S_2 \subseteq [m]$, define projection matrix $\P_{S_i} := \A^\top \I_{S_i}^\top (\I_{S_i}\A\A^\top\I_{S_i}^\top)^\dagger\I_{S_i}\A$ where $\I_{S_i} \in \R^{|S_i| \times m}$ is the sampling matrix. Then we have
\begin{align*}
\P_{S_1} \preceq \P_{S_2}.
\end{align*}
\end{lemma}

\begin{lemma}[Ghost coupling]\label{lem:ghost_coupling}
Conditioned on an event that holds with probability $0.99$ (and only depends on RHT). For $k \geq \log m$ and $\delta = m^{-O(1)}$, if we run Algorithm~\ref{alg:dpp_sample_ghost} with choice $\mathrm{call} \geq Ck$ for some constant $C = O(1)$, and $\mathrm{iter} = O(\log^3 m)$, then with probability $1 - \delta$, $S_{\mathrm{iter}}$ is the same as $S_{\dpp}$, where $S_{\dpp}\sim k$-$\dpp(\bar{\A}\bar{\A}^\top)$.
\end{lemma}

\begin{algorithm}[!ht]
\caption{Construct preconditioner for solving normal equation.}
\label{alg:preconditioner}
\begin{algorithmic}[1]
\State \textbf{Input: }matrix $\tilde{\A}\in\R^{\tau\times n}$;
\State Compute $\mathbf{\Phi}\tilde{\A}^\top$ by calling Lemma~\ref{lem:precondition_sparse}; \Comment{Sketch: takes $\tilde{O}(n\tau)$ time.}
\State Compute compact size SVD as $\mathbf{\Phi}\tilde{\A}^\top = \tilde{\U} \tilde{\mathbf{\Sigma}} \tilde{\V}^\top$; \Comment{Takes $O(\tau^\omega)$ time.}
\State Construct preconditioner $\mathbf{M} \leftarrow \tilde{\V} \tilde{\mathbf{\Sigma}}^{-1}$;
\\
\Return $\M$;
\end{algorithmic}
\end{algorithm}

\begin{lemma}[Convergence]\label{lem:approx_converge}
Given $\tilde{\A} \in \R^{\tau \times n}, \tilde{\b} \in \R^\tau$, let $\w^* = \tilde{\A}^\dagger\tilde{\b}$ be the least squares solution of $\tilde{\A}\w = \tilde{\b}$. Given $\delta <1/2$, if the subspace embedding matrix $\mathbf{\Phi} \in \R^{\phi\times n}$ from Lemma \ref{lem:precondition_sparse} satisfies $\phi = O(\tau+\log(1/\delta))$, then with probability $1 - \delta$, Algorithm~\ref{alg:preconditioner} outputs $\M$ in time $O(n\tau \log(\tau/\delta) + \tau^{\omega})$ such that $\tilde{\kappa} = \kappa(\tilde{\A}^\top\M) = O(1)$, and solving the following system
\begin{align}\label{eq:equi_cg}
(\M^\top \tilde{\A}\tilde{\A}^\top \M) \u = \M^\top\tilde{\b}, ~~~ \w = \tilde{\A}^\top \M\u
\end{align}
by using CG and starting from $\w_0 = \mathbf{0}$ will yield the following convergence result:
\begin{align*}
\|\w_s - \w^*\| \leq 2\left(\frac{\tilde{\kappa}-1}{\tilde{\kappa}+1}\right)^{s} \cdot \|\w^*\|.
\end{align*}
\end{lemma}

\begin{lemma}[Convergence of approximate sketch-and-project]\label{lem:main_convergence}
Given matrix $\A\in\R^{m\times n}$ with rank $r$, denote $\mathbf{Q} = \frac{1}{\sqrt{m}}\H \mathbf{D}$ as the RHT matrix and $\bar{\A} = \Q\A$ as the preprocessed matrix. Let $\I_{\tilde{S}}\in\R^{\tau \times m}$ be the sampling matrix and $\P_{\tilde{S}} := \bar{\A}^\top \I_{\tilde{S}}^\top(\I_{\tilde{S}}\bar{\A}\bar{\A}^\top\I_{\tilde{S}}^\top)^\dagger\I_{\tilde{S}}\bar{\A}$ be the corresponding projection matrix. Denote $\rho = \lambda_{\min}^+(\E[\P_{\tilde{S}}])$, then, running Algorithm~\ref{alg:main} with choice $s_{\max} = O(\log\frac{1}{\rho})$ will yield the following convergence result:
\begin{align*}
\E\|\x_{t+1} - \x^*\|^2 \leq \left(1 - \frac{\rho}{4}\right)\cdot \|\x_t - \x^*\|^2.
\end{align*}
\end{lemma}

\begin{algorithm}[!ht]
\caption{Least squares solver using gradient descent with inexact preconditioning.}
\label{alg:main_ls}
\begin{algorithmic}[1]
\State \textbf{Input: }matrix $\A\in\R^{n\times d}$, vector $\b \in \R^n$, uniform sample size $\tau$, iterate $\x_0$, inner CG iteration $s_{\max}$, inner iteration $t_{\max}$, outer iteration $T$;
\State Compute sketch $\tilde{\A} \leftarrow \mathbf{\Phi}\A$; \Comment{Takes $O(\nnz(\A)\log(d/\delta))$ time.}
\For{$t = 0, 1, \ldots, T-1$}
\State Compute $\g_t \leftarrow \A^\top(\A\x_t - \b)$; \Comment{Takes $O(\nnz(\A))$ time.}
\State Solve $\hat{\p}_t \approx (\tilde{\A}^\top\tilde{\A})^\dagger\g_t$ by calling Algorithm~\ref{alg:main_2} with choice $(\tilde{\A}, \g_t, \tau, \mathbf{0}, t_{\max}, s_{\max})$;
\State Compute $\x_{t+1} \leftarrow \x_t - \hat{\p}_t$;
\EndFor \\
\Return $\tilde{\x} = \x_{t_{\max}}$;
\end{algorithmic}
\end{algorithm}


