\lambda_{\min}^+(\E[\P_{\tilde{S}}]) \geq \frac{\tau / r}{2.5\bar{\kappa}_k^2\log^3 m}
\end{align*}
where $\P_{\tilde{S}} := \bar{\A}^\top \I_{\tilde{S}}^\top(\I_{\tilde{S}}\bar{\A}\bar{\A}^\top\I_{\tilde{S}}^\top)^\dagger\I_{\tilde{S}}\bar{\A}$ is the projection matrix and $\I_{\tilde{S}} \in \R^{\tau \times m}$ is the row sampling matrix according to $\tilde{S}$.
\end{lemma}
\begin{proof}[Proof of Lemma~\ref{lem:main_sampling}]
For $k\geq \log m$, we set $\tau \geq Ck\log^3 m$ for some constant $C = O(1)$ which is specified in the proof of Lemma~\ref{lem:ghost_coupling} and larger than $2$. We set $k' = \min\{\tau /\log^3 m, r\}$ and consider $\dpp$ sample $S_{\dpp}\sim k'$-$\mathrm{DPP}(\bar{\A}\bar{\A}^\top)$, and let $\P_{S_{\dpp}}$ be the corresponding projection matrix. Let $\tilde{S}$ be the output of Algorithm~\ref{alg:dpp_sample_real} with given $\tau$, and let $\P_{\tilde{S}}$ be the corresponding projection matrix. We define $\mathcal{E}$ as the event $\{S_{\dpp} \subseteq \tilde{S}\}$, then according to Lemma~\ref{lem:main_coupling}, event $\mathcal{E}$ holds with probability $1 - \delta$. Thus we have
\begin{align*}
\E[\P_{\tilde{S}}] = & ~ \E[\P_{\tilde{S}}\mid \mathcal{E}] \Pr\{\mathcal{E}\} + \E[\P_{\tilde{S}}\mid \mathcal{E}^c] \Pr\{\mathcal{E}^c\} \\
\succeq & ~\E[\P_{\tilde{S}}\mid \mathcal{E}] \Pr\{\mathcal{E}\} \\
\succeq & ~ \E[\P_{S_{\dpp}}\mid \mathcal{E}] \Pr\{\mathcal{E}\} \\
= & ~ \E[\P_{S_{\dpp}}] - \E[\P_{S_{\dpp}}\mid \mathcal{E}^c] \Pr\{\mathcal{E}^c\} \\
\succeq & ~ \E[\P_{S_{\dpp}}] - \Pr\{\mathcal{E}^c\}\cdot \I \\
= & ~ \E[\P_{S_{\dpp}}] - \delta \cdot \I
\end{align*}
where the first step follows from the law of total expectation, the second step follows since the projection matrices are PSD, the third step follows from the definition of $\mathcal{E}$ and Lemma~\ref{lem:project_order}, the fourth step follows from the law of total expectation, the fifth step follows from Lemma~\ref{lem:project_order} and the last step follows since $\Pr\{\mathcal{E}\} \geq 1- \delta$. Notice that since $\Q^\top\Q = \I$, we know that $\bar{\A} = \Q\A$ has the same spectrum as $\A$ and thus $\bar{\kappa}_{k}(\bar{\A})=\bar{\kappa}_{k}(\A)=\bar{\kappa}_{k}$. By applying Lemma~\ref{lem:improve_bound} to $\bar{\A}$ we know that $\lambda_{\min}^+(\E[\P_{S_{\dpp}}]) \geq \frac{k'-k}{k'-k-1 + (r-k)\bar{\kappa}_{k}^2}$. By combining this with the above result we have
\begin{align}\label{eq:S_lower_bound}
\lambda_{\min}(\E[\P_{\tilde{S}}]) \geq & ~ \lambda_{\min}^+(\E[\P_{S_{\dpp}}]) - \delta \nonumber \\
\geq & ~ \frac{k'-k}{k'-k-1 + (r-k)\bar{\kappa}_{k}^2} - \delta \nonumber \\
> & ~ \frac{\tau - k\log^3 m}{\tau-k\log^3 m + (r-k)\bar{\kappa}_{k}^2\log^3 m} - \delta \nonumber \\
= & ~ \frac{\tau - k\log^3 m}{\tau-(\bar{\kappa}_{k}^2+1)k\log^3 m + r\bar{\kappa}_{k}^2\log^3 m} - \delta
\end{align}
where the third step follows from $k' \leq \tau /\log^3 m$. We can verify that by treating $\bar{\kappa}_{k}$ as a constant and considering the above expression (Eq.\eqref{eq:S_lower_bound}) as a function of $k$, then this expression is decreasing in $k$. By using $k\leq \tau/(C\log^3 m)$, we have
\begin{align*}
\lambda_{\min}(\E[\P_{\tilde{S}}]) \geq & ~ \frac{(C-1)\tau}{C\tau-(\bar{\kappa}_{k}^2+1)\tau + Cr\bar{\kappa}_{k}^2\log^3 m} - \delta \\
= & ~ \frac{(C-1)\tau / r}{(C-1-\bar{\kappa}_k^2)\tau / r + C\bar{\kappa}_k^2\log^3 m} - \delta.
\end{align*}
We consider two cases here. If $\bar{\kappa}_k^2 \geq C-1$, then by using $C\geq 2$ we have
\begin{align*}
\lambda_{\min}(\E[\P_{\tilde{S}}]) \geq \frac{(C-1)\tau / r}{C\bar{\kappa}_k^2\log^3 m} - \delta \geq \frac{\tau / r}{2\bar{\kappa}_k^2\log^3 m} - \delta.
\end{align*}
If $\bar{\kappa}_k^2 < C-1$, then we use the assumption that $\tau / \log^3 m \leq r$ (otherwise we can simply choose $k' = r$ which is the trivial case) and have
\begin{align*}
\lambda_{\min}(\E[\P_{\tilde{S}}]) \geq & ~ \frac{(C-1)\tau / r}{(C-1-\bar{\kappa}_k^2)\log^3 m + C\bar{\kappa}_k^2\log^3 m} - \delta \\
= & ~ \frac{(C-1)\tau / r}{(C-1)\log^3 m + (C-1)\bar{\kappa}_k^2\log^3 m} - \delta \\
= & ~ \frac{\tau / r}{(\bar{\kappa}_k^2+1)\log^3 m} - \delta
\geq \frac{\tau / r}{2\bar{\kappa}_k^2\log^3 m} - \delta
\end{align*}
where we use the fact that $\bar{\kappa}_k\geq 1$. Finally, according to Remark~\ref{rem:anari_constant} we can see that the failure probability is actually $\delta = m^{-9}$. After some calculation we know that as long as $\bar{\kappa}_k \leq m^4$, we have the following holds:
\begin{align*}
\lambda_{\min}^+(\E[\P_{\tilde{S}}]) \geq \frac{\tau / r}{2\bar{\kappa}_k^2\log^3 m} - \frac{1}{m^9} \geq \frac{\tau / r}{2.5\bar{\kappa}_k^2\log^3 m}.
\end{align*}
\end{proof}

\begin{theorem}[Fast coordinate descent-type solver]\label{thm:main_2}
Given matrix $\A\in\R^{m\times n}$ with $\rank(\A) = r$ and $\b \in \R^m$, let $\{\sigma_i\}_{i=1}^r$ be the singular values of $\A$ in decreasing order. For $\log n \leq k < r$, define $\bar{\kappa}_k := (\frac{1}{r-k}\sum_{j > k}^r \sigma_j^2 / \sigma_r^2)^{1/2}$ and assume for simplicity that $\bar{\kappa}_k \leq m^4$.
Let $\x^* = \A^\dagger\b$ be the least squares solution of the (possibly inconsistent) linear system $\A\x = \b$. Assume $\x_0 - \x^*$ is not in the nullspace of $\A$. Then conditioned on an event that holds with probability $0.99$ (and only depends on $\frac{1}{\sqrt{n}}\A\D\H$), for $C = O(1)$, running Algorithm~\ref{alg:main_2} with choice $\c = \A^\top\b, \tau \geq Ck \log^3 n$ and $s_{\max} = O(\log(r\bar{\kappa}_k / \tau))$ will yield the following convergence result:
\begin{align*}
\E\|\A(\x_t - \x^*)\|^2 \leq \left(1 - \frac{\tau / r}{10\bar{\kappa}_k^2\log^3 n}\right)^t \cdot \|\A(\x_0 - \x^*)\|^2.
\end{align*}
By further choosing $\tau = O(k\cdot \log^3 n), \x_0 = \mathbf{0}$ and $t_{\max} = O(r\bar{\kappa}_k^2/k \cdot \log(1/\epsilon))$ for given $\epsilon>0$, Algorithm~\ref{alg:main_2} outputs $\tilde{\x}$ such that $\|\A(\tilde{\x} - \x^*)\|^2 \leq \epsilon \|\A\x^*\|^2$ holds with probability $0.98$ in time:
\begin{align*}
O\Big(mn \log n + (mr \log^4 n + rk^{\omega-1} \log^{3\omega}n)\cdot\bar{\kappa}_k^2\log1/\epsilon\Big).
\end{align*}
\end{theorem}
\begin{proof}[Proof of Theorem~\ref{thm:main_2}]
In the algorithm, we preprocess the $\A^\top\A\x=\c$ linear system (from both left and right) with $\Q=\frac1{\sqrt n}\H\D$:
\begin{align*}
(\Q\A^\top)(\A\Q^\top)\z = \Q\c, ~~~\x = \Q^\top\z.
\end{align*}
For notation convenience we use $\A$ and $\c$ to denote the ones after randomized Hadamard transform (which is the original $\A\Q^\top$ and $\Q\c$), and we will transform back to the original $\A$ and $\c$ in the end of the proof. Thus we need to solve the implicit PSD linear system $\A^\top\A\z = \c$, where the optimal solution is $\z^* = (\A^\top\A)^\dagger\c$. Denote $\I_{\tilde{S}}^\top\in\R^{n \times \tau}$ as the column sampling matrix where $\tilde{S}$ is the output of Algorithm~\ref{alg:dpp_sample_real} and $\tilde{\A} = \A\I_{\tilde{S}}^\top \in \R^{m\times \tau}$. Consider the following sketch-and-project update rule:
\begin{align}\label{eq:exact_sketch_proj}
\z_{t+1} = \z_t - \I_{\tilde{S}}^\top(\I_{\tilde{S}}\A^\top\A\I_{\tilde{S}}^\top)^\dagger\I_{\tilde{S}}(\A^\top\A\z_t - \c).
\end{align}
Denote $\y_t = \A\z_t$ and $\tilde{\c} = \tilde{\A}^\top\y_t - \I_{\tilde{S}}\c$, by right multiplying by $\A$ we have
\begin{align*}
\y_{t+1} = \y_t - \tilde{\A}(\tilde{\A}^\top\tilde{\A})^\dagger(\tilde{\A}^\top\y_t - \I_{\tilde{S}}\c) = \y_t - \tilde{\A}\underbrace{(\tilde{\A}^\top\tilde{\A})^\dagger\tilde{\c}}_{\w_t^*}.
\end{align*}
Similarly, instead of directly computing $\w_t^*$ we consider solving the sub-problem $\tilde{\A}^\top\tilde{\A}\w = \tilde{\c}$. We construct the preconditioner $\M$ similarly as Lemma~\ref{lem:approx_converge}, and consider the following linear system
\begin{align*}
\M^\top\tilde{\A}^\top\tilde{\A}\M \u = \M^\top\tilde{\c}, ~~~\w = \M\u,
\end{align*}
then Lemma~\ref{lem:approx_converge} guarantees that $\tilde{\kappa} = \kappa(\tilde{\A}\M) = O(1)$ holds with probability $1-\delta_1$. Denote $\u^* = \M^{-1}(\tilde{\A}^\top\tilde{\A})^\dagger\tilde{\c}$ as the optimal solution, by calling $\mathrm{CG}(\M^\top\tilde{\A}^\top, \M^\top\tilde{\c}, s)$ and starting from $\u_0 = \mathbf{0}$, Lemma~\ref{lem:cg} gives the following convergence result:
\begin{align*}
\|\tilde{\A}\M(\u_s - \u^*)\| \leq 2\left(\frac{\tilde{\kappa}-1}{\tilde{\kappa}+1}\right)^{s} \cdot \|\tilde{\A}\M\u^*\|.
\end{align*}
where $\tilde{\kappa} = O(1)$ holds with probability $1-\delta_1$. Define $\mathcal{E}$ as the event that $\tilde{\kappa} = O(1)$, if event $\mathcal{E}$ holds, then by choosing $s_{\max} = O(\log(1/\epsilon))$ and changing the variable back from $\u$ to $\w$ we have
\begin{align*}
\|\tilde{\A}(\w_{s_{\max}} - \w_t^*)\| \leq \epsilon\|\tilde{\A}\w_t^*\|.
\end{align*}
Denote $\tilde{\z}_{t+1} = \z_t - \I_{\tilde{S}}^\top \w_t^*$ as the update of \textbf{exact} sketch-and-project, notice that our approximate update is $\z_{t+1} = \z_t - \I_{\tilde{S}}^\top\w_{s_{\max}}$. Denote $\Delta_t = \|\A(\tilde{\z}_{t+1} - \z_{t+1})\|$ as the matrix $\A$ norm difference between our approximate update and exact sketch-and-project update, and we bound it as
\begin{align*}
\Delta_t = & ~ \|\A(\tilde{\z}_{t+1} - \z_{t+1})\| 
=\|\tilde{\A} (\w_{s_{\max}} -\w_t^*)\|\\
\leq & ~ \epsilon \|\tilde{\A}\w_t^*\| 
=  \epsilon \|\A\tilde{\z}_{t+1} - \A\z_t\| \\
\leq & ~ \epsilon (\|\A\tilde{\z}_{t+1} -\A\z^*\| +\|\A\z_{t} -\A\z^*\|) 
\leq  2\epsilon\|\A(\z_{t} - \z^*)\|.
\end{align*}
Notice that $\tilde{\z}_{t+1}$ is the same as the update of exact block coordinate descent on the PSD linear system $\A^\top\A\z=\c$, so similarly as before, we have:
\begin{align*}
\E\|\A(\tilde{\z}_{t+1} - \z^*)\|^2 
\leq & ~ (1-\lambda_{\min}^+(\E[\P_S]))\cdot \| \A(\z_t-\z^*)\|^2 \\
=  & ~ (1-\rho)\cdot \| \A(\z_t-\z^*)\|^2.
\end{align*}
where we denote $\rho = \lambda_{\min}^+(\E[\P_{S}])$. By combining the above two results we have
\begin{align*}
 \E\|\A(\z_{t+1} - \z^*)\|^2 
= & ~ \E\|(\A\z_{t+1} - \A\tilde{\z}_{t+1}) + (\A\tilde{\z}_{t+1} - \A\z^*)\|^2 \\
\leq & ~ \Delta_t^2 + \E\|\A(\tilde{\z}_{t+1} - \z^*)\|^2 + 2\Delta_t \cdot (\E\|\A(\tilde{\z}_{t+1} - \z^*)\|^2)^{1/2} \\
\leq & ~ \Delta_t^2 + (1-\rho)\cdot \| \A(\z_t-\z^*)\|^2 + 2\Delta_t\sqrt{1-\rho}\cdot\E\|\A(\z_{t+1} - \tilde{\z}_{t+1})\| \\
= & ~ (\sqrt{1-\rho}\cdot \|\A(\z_t-\z^*)\| + \Delta_t)^2.
\end{align*}
Notice that if event $\mathcal{E}$ holds, then we have $\Delta_t \leq 2\epsilon \|\A(\z_t-\z^*)\|$ by choosing $s_{\max} = \log(1/\epsilon)$. If event $\mathcal{E}$ does not hold, we use the same trick as in the proof of Lemma~\ref{lem:main_convergence} and bound $\Delta_t$ as $\Delta_t \leq 8 \|\A(\z_t - \z^*)\|$. To conclude we have
\begin{align*}
\E\|\A(\z_{t+1} - \z^*)\|^2 = & ~ \E[\|\A(\z_{t+1} - \z^*)\|^2 \mid \mathcal{E}] \cdot\Pr\{\mathcal{E}\} + \E[\|\A(\z_{t+1} - \z^*)\|^2 \mid \bar{\mathcal{E}}] \cdot\Pr\{\bar{\mathcal{E}}\} \\
\leq & ~ (1-\delta_1)\cdot(\sqrt{1-\rho} +2\epsilon)^2\|\A(\z_t-\z^*)\|^2 + \delta_1\cdot (\sqrt{1-\rho} + 8)^2\|\A(\z_t-\z^*)\|^2 \\
\leq & ~ [(\sqrt{1-\rho} +2\epsilon)^2 + 81\delta_1]\cdot \|\A(\z_t-\z^*)\|^2.
\end{align*}
We set $\epsilon = \rho / 8$ and $\delta_1 = \rho/324$, notice that $\sqrt{1 - \rho} + \rho / 4 \leq \sqrt{1 - \rho / 2}$, thus we have
\begin{align*}
\E\|\A(\z_{t+1} - \z^*)\|^2 \leq \left(1 - \frac{\rho}{4}\right)\cdot \|\A(\z_t-\z^*)\|^2.
\end{align*}
By applying Lemma~\ref{lem:main_sampling} to $\A^\top$, we know that by setting $\tau \geq Ck\log^3 n$ for some constant $C = O(1)$, then we have $\rho \geq \frac{\tau / r}{2.5\bar{\kappa}_k^2\log^3 n}$. By combining this with the above result we have
\begin{align*}
\E\|\A(\z_t - \z^*)\|^2 \leq \left(1 - \frac{\tau / r}{10\bar{\kappa}_k^2\log^3 n}\right)^t \cdot \|\A(\z_0 - \z^*)\|^2.
\end{align*}
Notice that this is the convergence result for solving $\A^\top\A\z = \c$ for an arbitrary $\c$. By choosing $\c = \A^\top\b$, we have $\z^* = (\A^\top\A)^\dagger\c = (\A^\top\A)^\dagger\A^\top\b = \A^\dagger\b$ which is the least squares solution of linear system $\A\z = \b$ we want. Finally, notice that both the matrix $\A$ and vector $\c$ here are after the randomized Hadamard transform, and we need to transform the variable back. Since $\Q^\top\Q=\I$, the quantity $\A\z$ here is the identical to the original $\A\x$, thus we have
\begin{align*}
\E\|\A(\x_t - \x^*)\|^2 \leq \left(1 - \frac{\tau / r}{10\bar{\kappa}_k^2\log^3 n}\right)^t \cdot \|\A(\x_0 - \x^*)\|^2.
\end{align*}
By further choosing $\tau = O(k\cdot \log^3 n), \x_0 = \mathbf{0}$ and $t_{\max} = O(r\bar{\kappa}_k^2/k \cdot \log(100/\epsilon))$ we have $\E\|\A(\x_t - \x^*)\|^2 \leq \frac{\epsilon}{100} \|\A\x^*\|^2$. By applying Markov's inequality we have $\|\A(\x_t - \x^*)\|^2 \leq \epsilon \|\A\x^*\|^2$ holds with probability $0.98$. Finally by using Lemma~\ref{lem:precondition_sparse} we compute the total cost as
\begin{align*}
& ~ O(mn\log n) + t_{\max} \cdot O(m\tau \log(\tau/\delta_1) + \tau^{\omega} + m\tau s_{\max}) \\
= & ~ O(mn\log n) + r\bar{\kappa}_k^2/k \cdot \log(100/\epsilon) \cdot O(mk \log^3 n \log (r\bar{\kappa}_k) + k^\omega \log^{3\omega} n) \\
= & ~ O(mn \log n + (mr\log^3 n \log (r\bar{\kappa}_k) + rk^{\omega-1} \log^{3\omega}n)\cdot\bar{\kappa}_k^2\log1/\epsilon) \\
= & ~ O(mn \log n + (mr\log^4 n + rk^{\omega-1} \log^{3\omega}n)\cdot\bar{\kappa}_k^2\log1/\epsilon)
\end{align*}
where the last step follows from the assumption $\bar{\kappa}_k \leq n^4$ and thus $\log (r\bar{\kappa}_k) = O(\log n)$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
Given $\A\in\R^{n \times d}$ with $\rank(\A) = r$ and $\b \in \R^n$, we consider solving the least squares problem $\x^* = \argmin_{\x}\|\A\x-\b\|$ with (approximate) preconditioned gradient descent
\begin{align*}
\x_{t+1} = \x_t - \tilde{\H}^\dagger \g_t = \x_t - \underbrace{(\tilde{\A}^\top\tilde{\A})^\dagger (\A^\top\A\x_t - \A^\top\b)}_{\p_t^*}
\end{align*}
where $\tilde{\H} = \tilde{\A}^\top\tilde{\A} = \A^\top\mathbf{\Phi}^\top\mathbf{\Phi}\A$ is such that $\tilde{\H} \approx_{1+\epsilon_H} \H = \A^\top\A$ for some constant $\epsilon_H$ that will be specified later. By using the fact that $\H(\x_t - \x^*) = \g_t$ we have $\|\g_t\|_{\H^\dagger} = \|\x_t - \x^*\|_{\H}$, and
\begin{align*}
\|\x_t - \p_t^* - \x^*\|_{\H}^2 = & ~ \|\x_t - \x^*\|_{\H}^2 - 2(\x_t - \x^*)^\top\H\p_t^* + \|\p_t^*\|_{\H}^2 \\
= & ~ \|\x_t - \x^*\|_{\H}^2 - 2\g_t^\top\tilde{\H}^\dagger\g_t + \|\H^{1/2}\tilde{\H}^\dagger\g_t\|^2 \\
\leq & ~ \|\x_t - \x^*\|_{\H}^2 - 2\|\g_t\|_{\tilde{\H}^\dagger}^2 + (1+\epsilon_H) \|\g_t\|_{\tilde{\H}^\dagger}^2 \\
= & ~ \|\x_t - \x^*\|_{\H}^2 - (1-\epsilon_H)\|\g_t\|_{\tilde{\H}^\dagger}^2 \\
\leq & ~ \|\x_t - \x^*\|_{\H}^2 - (1-\epsilon_H)^2\|\g_t\|_{\H^\dagger}^2 \\
\leq & ~ 2 \epsilon_H\cdot \|\x_t - \x^*\|_{\H}^2
\end{align*}
By choosing $\epsilon_H = 1/ 8$ we have $\|\x_t - \p_t^* - \x^*\|_{\H} \leq \frac{1}{2}\|\x_t-\x^*\|_{\H}$. Suppose for now that we can construct a randomized estimate $\hat{\p}_t$ such that $\E_t[\|\hat{\p}_t - \p_t^*\|_{\tilde{\H}}] \leq \frac{1}{4} \|\p_t^*\|_{\tilde{\H}}$, where $\E_t$ is the expectation conditioned on $\x_t$ and $\tilde\H$. Then, since we also assume that $\tilde{\H} \approx_{1+\epsilon_H} \H$ for $\epsilon_H = 1/8$, we have
\begin{align*}
\E_t\big[\|\hat{\p}_t - \p_t^*\|_{\H}\big] \leq \sqrt{1+\epsilon_H} \E_t\big[\|\hat{\p}_t - \p_t^*\|_{\tilde{\H}}\big] \leq \frac{\sqrt{1+\epsilon_H}}{4} \|\p_t^*\|_{\tilde{\H}} \leq \frac{1+\epsilon_H}{4} \|\p_t^*\|_{\H} \leq \frac{1}{3} \|\p_t^*\|_{\H}.
\end{align*}
By combining the above two results we have
\begin{align*}
\E_t\big[\|\A(\x_{t+1} - \x^*)\|\big]
= & ~ \E_t\big[\|\x_t - \hat{\p}_t - \x^*\|_{\H}\big] \\
\leq & ~ \|\x_t - \x^* - \p_t^*\|_{\H} + \E_t\big[\|\p_t^* - \hat{\p}_t\|_{\H}\big] \\
\leq & ~ \frac{1}{2}\|\x_t -\x^*\|_{\H} + \frac{1}{3} \|\p_t^*\|_{\H} \\
= & ~ \frac{1}{2}\|\x_t -\x^*\|_{\H} + \frac{1}{3} \|\g_t\|_{\H^\dagger} \\
= & ~ \frac{5}{6} \|\A(\x_t - \x^*)\|.
\end{align*}
To achieve this convergence result, there are two parts left that need to be done: (i) construct the preconditioner $\tilde{\H} = \tilde{\A}^\top\tilde{\A}$ such that $\tilde{\H} \approx_{1+1/8} \H$ is a spectral approximation; and (ii) compute the randomized estimate $\hat{\p}_t$ such that $\E_t\big[\|\hat{\p}_t - \p_t^*\|_{\tilde{\H}}\big] \leq \frac{1}{4} \|\p_t^*\|_{\tilde{\H}}$.
For the first part, we use sparse embedding matrix to construct $\tilde{\A} = \mathbf{\Phi}\A$. According to Lemma~\ref{lem:precondition_sparse} we know $\tilde{\A}^\top\tilde{\A} \approx_{1+1/8} \A^\top\A$ holds with probability at least $1-\delta_1$ by choosing $\phi = O(d+\log(1/\delta_1))$, and the construction takes $O(\nnz(\A)\log(d/\delta_1) + d^2\log^4 (d/\delta_1))$ time. 

For the second part, to approximate $\p_t^*$, we treat it as solving the linear system $(\tilde{\A}^\top\tilde{\A}) \p = \g_t$ where $\tilde{\A} \in \R^{\phi \times d}$ for $\phi = O(d+ \log (1 / \delta_1))$ and $\g_t = \A^\top(\A\x_t - \b)$ is given. Notice that since $\tilde{\A}^\top\tilde{\A}$ is an $(1+\frac{1}{8})$-spectral approximation of $\A^\top\A$, we know that all the singular values of $\tilde{\A}$ are constant factor approximations of the singular values of $\A$, thus we know $\bar{\kappa}_k(\tilde{\A})$ and $\bar{\kappa}_k(\A)$ only differs within a constant factor. We apply Algorithm~\ref{alg:main_2} to $(\tilde{\A}\in\R^{\phi\times d}, \c = \g_t, \p_0 = \mathbf{0})$ with choice $\tau \geq Ck\log^3 d, s_{\max} = O(\log(r\bar{\kappa}_k/k))$ and $t_{\max} = O(r\bar{\kappa}_k^2/k)$ (note that the RHT preprocessing step from line 2 can use the same RHT across all gradient descent iterations). According to the proof of Theorem~\ref{thm:main_2}, we know that with the right choice of constants the output $\hat{\p}_t$ will satisfy $\E_t[\|\hat{\p}_t - \p_t^*\|_{\tilde{\H}}] \leq \frac{1}{4} \|\p_t^*\|_{\tilde{\H}}$ in time
\begin{align*}
O(\phi d \log d + (\phi r \log^4 d + rk^{\omega-1}\log^{3\omega}d)\bar{\kappa}_k^2) = O((d^2\log^4 d + dk^{\omega-1}\log^{3\omega}d)\cdot \bar{\kappa}_k^2).
\end{align*}
With the above analysis,  we have the following convergence result, where the expectation is taken over the entire run of the algorithm, conditioning on successful construction and preprocessing of $\tilde\A$ (which holds with high probability):
\begin{align*}
 \E\big[\|\A(\x_T-\x^*)\|\big]\leq \Big(\frac 56\Big)^{T}\|\A(\x_0-\x^*)\|
\end{align*}
Thus by choosing $\x_0=\mathbf 0$, $T = O(\log(1/\epsilon))$, using Markov's inequality we can obtain that with probability 0.99, $\tilde{\x} = \x_T$ will satisfy $\|\A(\tilde\x-\x^*)\|^2\leq\epsilon^2\|\b\|^2$, which in turn implies $\|\A\tilde{\x} - \b\|^2 \leq \|\A\x^* - \b\|^2+\epsilon\|\b\|^2$.
The overall time complexity of the procedure is:
\begin{align*}
& ~ O\left(\nnz(\A)\log d + d^2\log^4 d + (\nnz(\A) + \bar{\kappa}_k^2 d^2\log^4 d + \bar{\kappa}_k^2 dk^{\omega-1}\log^{3\omega}d)\log1/\epsilon\right)\\
= & ~ O\left(\nnz(\A)\log(d/\epsilon) + (d^2\log^4 d + dk^{\omega-1}\log^{3\omega}d)\cdot \bar{\kappa}_k^2\log1/\epsilon\right).
\end{align*}

\end{proof}
